import * as OurXmlization from "../src/xmlization";
import * as OurTypes from "../src/types";

import * as TestCommonXmlization from "./commonXmlization";

test(
  "INode XML round-trip " +
  "starting from Branch OK",
  () => {
    const instance = TestCommonXmlization.loadMinimalBranch();

    const xmlText = OurXmlization.toXmlString(instance);
    const anotherInstanceOrError = OurXmlization.fromXmlString(xmlText);
    expect(anotherInstanceOrError.error).toBeNull();
    const anotherInstance = anotherInstanceOrError.mustValue();

    const asInterface = OurTypes.asNode(anotherInstance);
    expect(asInterface).not.toBeNull();
  }
);

test(
  "INode XML round-trip via " +
  "nodeFromXmlString starting from Branch OK",
  () => {
    const instance = TestCommonXmlization.loadMinimalBranch();

    const xmlText = OurXmlization.toXmlString(instance);
    const anotherInstanceOrError = OurXmlization.nodeFromXmlString(
      xmlText
    );
    expect(anotherInstanceOrError.error).toBeNull();
  }
);

